L000413	\includegraphics[width=1.05\columnwidth]{Cm_modes.png}
L000414	\caption{Evolution of the amplitudes of the non axisymmetric $m=1$ and $m=2$ density modes,
L000415	normalized by the $m=0$ mode. Solid lines denote the magnetized cases, while dashed lines indicate
L000416	the {unmagnetized} cases reported in \cite{Tsokaros:2022hjk}.}
